        locations: ["sky-citadel", "sky-haven", "sky-needle", "satellite-graveyard", "the-broadcast-tower", "ghost-relay", "dead-satellite-field", "graveyard-orbit", "weather-station-prime"],
        characters: ["Prophet NULL"]
